<?php require "config.php";$page_title="Contact";$ok=false;if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$conn->prepare("INSERT INTO inquiries(name,email,message) VALUES(?,?,?)");$s->bind_param("sss",$_POST["name"],$_POST["email"],$_POST["message"]);$s->execute();$ok=true;}require "includes/header.php";?><section class="page-banner"><div class="container"><div class="eyebrow">Get in touch</div><h1 class="display-5 fw-bold mt-3">Talk to CGUA.</h1></div></section><section class="section"><div class="container col-lg-7"><?php if($ok):?><div class="alert alert-success">Message received.</div><?php endif;?><form method="post" class="dashboard-card"><input class="form-control mb-3" name="name" placeholder="Name" required><input class="form-control mb-3" type="email" name="email" placeholder="Email" required><textarea class="form-control mb-3" name="message" rows="6" placeholder="Message" required></textarea><button class="btn btn-adventure rounded-pill">Send Message</button></form></div></section><?php require "includes/footer.php";?>